// План: .qa/e2e/specs/placement-results.md, тест 1.4; кейсы PR-04, PR-06 (.qa/tests/placement-results.md).
// Запасной путь (autotest-writer): адаптивный цикл, window.confirm, два окна. Не прогонять при записи — запуск по /qa-regress.
import { test, expect } from '../../fixtures';
import { annotateCleanup, createChild, levelLines, passPlacement, qaChildName, startPlacementAsChild } from './placement.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe('Результаты стартового теста — новый ребёнок (C3 и уровни у родителя)', () => {
  test('Неуверенное прохождение: родитель видит «עדיין לא ודאי», а не одну цифру; «אחר כך» ведёт домой @desktop @data #c121d3', async ({ asUser }, testInfo) => {
    test.setTimeout(6 * 60_000); // длинное адаптивное прохождение, не пауза
    const kid = await asUser('parent');

    const childName = qaChildName();
    const childId = await createChild(kid, childName);
    annotateCleanup(testInfo, childName, childId);

    await startPlacementAsChild(kid, childId, childName);
    // Чтение — «לא בטוח/ה» на каждый текст; письмо — «abc» (первая попытка → «בואו ננסה עוד פעם!», вторая сохраняется)
    const writing = await passPlacement(kid, { reading: 'לא בטוח/ה', writing: 'unsure' });
    // #a0f00f: короткий / не на иврите ответ просит попробовать ещё раз (промежуточная проверка пути).
    // Если поведение второй попытки другое — цикл не дойдёт до C3 или retryPrompts = 0: остановиться и сообщить.
    expect(writing.retryPrompts, 'хотя бы раз показано «בואו ננסה עוד פעם!»').toBeGreaterThan(0);

    // C3 → «אחר כך» → дом ребёнка (S-07 «הפעולה הבטוחה הבאה»)
    await expect(kid.getByText(`כל הכבוד, ${childName}!`)).toBeVisible();
    await kid.getByRole('button', { name: 'אחר כך' }).click();
    await kid.waitForURL(/\/home$/);

    // Зона родителя — отдельное окно, второй слот входа того же родителя
    const parent = await asUser('parent-3');
    await parent.goto(`/children/${childId}`);
    const lines = levelLines(parent);
    await expect(lines.block).toBeVisible();

    // AC4: неуверенность, а не одна цифра
    // Числа на сайте обёрнуты в метки направления U+2066…U+2069 — сравниваем регуляркой, а не точной строкой.
    await expect(lines.reading).toHaveText(/^קריאה: עדיין לא ודאי · משוער [\u2066-\u2069]?1 \/ 10[\u2066-\u2069]?, יתעדכן אחרי כמה תרגולים$/);
    await expect(lines.writing).toContainText('עדיין לא ודאי');
    await expect(lines.writing).toContainText('1 / 4');
    // Нет строк с голой цифрой
    await expect(lines.reading).not.toHaveText(/קריאה: [\u2066-\u2069]?\d+ \/ 10/);
    await expect(lines.writing).not.toHaveText(/כתיבה: [\u2066-\u2069]?\d+ \/ 4/);
  });
});
